/* DLVA Question Bank — shared page chrome and helpers.
   Every page sets <body data-page="..." data-root=".."> and this file builds the
   top bar, sidebar, pager, in-page TOC, math rendering and diagrams. */
(function () {
  "use strict";

  const PAGES = [
    { id: "home", href: "index.html", title: "Home", group: "Start" },
    { id: "format", href: "exam-format.html", title: "Exam format & strategy", group: "Start" },
    // Lecture entries come from assets/lectures.js (generated by tools/make_pages.py).
    ...(window.DLVA_LECTURES || []).map((l) => ({ id: l.id, href: "lectures/" + l.id + ".html", num: String(+l.id.slice(1)), title: l.nav, date: l.dateShort,
      group: l.phase === "pre" ? "Lectures before midterm" : "Lectures after midterm" })),
    { id: "sample", href: "sample-midterm.html", num: "S", title: "Sample midterm — solved", group: "Practice" },
    { id: "mock", href: "mock-paper.html", num: "M", title: "Mock paper generator", group: "Practice" },
  ];
  // Pages that exist in the repo right now (the nav hides links to pages not yet written).
  const AVAILABLE = window.RL_AVAILABLE || null;

  const body = document.body;
  const ROOT = (body.dataset.root || ".").replace(/\/$/, "");
  const PAGE = body.dataset.page || "";
  const url = (href) => (ROOT === "." ? href : ROOT + "/" + href);
  const store = {
    get(k, d) { try { const v = localStorage.getItem("dlva:" + k); return v === null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem("dlva:" + k, JSON.stringify(v)); } catch (e) { /* storage unavailable */ } },
  };

  /* ---------- Theme ---------- */
  const savedTheme = store.get("theme", null);
  if (savedTheme) document.documentElement.dataset.theme = savedTheme;
  function currentTheme() {
    const t = document.documentElement.dataset.theme;
    if (t) return t;
    return window.matchMedia && matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  }

  /* ---------- Chrome ---------- */
  function el(tag, attrs, html) {
    const e = document.createElement(tag);
    if (attrs) for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (html !== undefined) e.innerHTML = html;
    return e;
  }

  function buildChrome() {
    const top = el("header", { class: "topbar" });
    top.innerHTML =
      '<button class="icon-btn menu-btn" aria-label="Open navigation">&#9776;</button>' +
      '<a class="brand" href="' + url("index.html") + '">DLVA Question Bank <span>· DS 265o, IISc</span></a>' +
      '<div class="spacer"></div>' +
      '<div class="search-wrap"><input class="search-input" type="search" placeholder="Search topics…" aria-label="Search">' +
      '<div class="search-results" role="listbox"></div></div>' +
      '<span class="reader-tools">' +
      '<button class="icon-btn size-btn" data-size="-1" aria-label="Smaller text" title="Smaller text">A−</button>' +
      '<button class="icon-btn size-btn" data-size="1" aria-label="Larger text" title="Larger text">A+</button>' +
      '<button class="icon-btn focus-btn" aria-label="Focus mode" title="Focus mode: hide the sidebar">⤢</button>' +
      "</span>" +
      '<button class="icon-btn theme-btn" aria-label="Toggle dark mode" title="Toggle dark mode"></button>';

    const side = el("nav", { class: "sidebar", "aria-label": "Chapters" });
    const done = store.get("done", {});
    let group = null, html = "";
    PAGES.forEach((p) => {
      if (AVAILABLE && !AVAILABLE.includes(p.id)) return;
      if (p.group !== group) { group = p.group; html += "<h4>" + group + "</h4>"; }
      const num = p.num ? '<span class="num">' + p.num + "</span>" : '<span class="num">•</span>';
      const dot = done[p.id] ? '<span class="done-dot" title="Marked as studied"></span>' : "";
      html += '<a href="' + url(p.href) + '" data-id="' + p.id + '"' + (p.id === PAGE ? ' class="active"' : "") + ">" +
        num + "<span>" + p.title + "</span>" + dot + "</a>";
      if (p.id === PAGE) html += '<div class="page-toc"></div>';
    });
    side.innerHTML = html;

    const main = document.querySelector("main.content");
    const layout = el("div", { class: "layout" });
    main.parentNode.insertBefore(top, main);
    main.parentNode.insertBefore(layout, main);
    layout.appendChild(side);
    layout.appendChild(main);

    const themeBtn = top.querySelector(".theme-btn");
    const paintThemeBtn = () => { themeBtn.textContent = currentTheme() === "dark" ? "☀" : "☾"; };
    paintThemeBtn();
    themeBtn.addEventListener("click", () => {
      const next = currentTheme() === "dark" ? "light" : "dark";
      document.documentElement.dataset.theme = next;
      store.set("theme", next);
      paintThemeBtn();
      document.dispatchEvent(new CustomEvent("themechange"));
    });
    setupReaderTools(top);
    top.querySelector(".menu-btn").addEventListener("click", () => body.classList.toggle("nav-open"));
    side.addEventListener("click", (e) => { if (e.target.closest("a")) body.classList.remove("nav-open"); });

    decorateHero();
    buildPageToc(side.querySelector(".page-toc"));
    buildPager(main);
    buildDoneToggle();
    setupSearch(top);
  }

  /* ---------- Reading aids: text size, focus mode, progress bar, back-to-top, reading time ---------- */
  function setupReaderTools(top) {
    const SIZES = [16, 17, 18, 19, 20, 21];
    let size = store.get("readSize", null);
    const apply = () => {
      if (size) document.documentElement.style.setProperty("--read-size", size + "px");
      else document.documentElement.style.removeProperty("--read-size");
    };
    apply();
    top.querySelectorAll(".size-btn").forEach((b) => b.addEventListener("click", () => {
      const cur = size || parseInt(getComputedStyle(document.documentElement).getPropertyValue("--read-size"), 10) || 18;
      const i = Math.max(0, Math.min(SIZES.length - 1, SIZES.indexOf(cur) + +b.dataset.size));
      size = SIZES[i === -1 ? 2 : i]; store.set("readSize", size); apply();
    }));
    const fb = top.querySelector(".focus-btn");
    const paintFocus = () => fb.classList.toggle("on", body.classList.contains("focus"));
    if (store.get("focus", false)) body.classList.add("focus");
    paintFocus();
    fb.addEventListener("click", () => { body.classList.toggle("focus"); store.set("focus", body.classList.contains("focus")); paintFocus(); });

    const bar = el("div", { class: "read-progress", "aria-hidden": "true" });
    const up = el("button", { class: "to-top", type: "button", "aria-label": "Back to top", title: "Back to top" }, "↑");
    body.appendChild(bar); body.appendChild(up);
    up.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));
    const onScroll = () => {
      const h = document.documentElement.scrollHeight - innerHeight;
      bar.style.width = (h > 0 ? (scrollY / h) * 100 : 0) + "%";
      up.classList.toggle("show", scrollY > 900);
    };
    document.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
  }

  function decorateHero() {
    const hero = document.querySelector(".hero");
    if (!hero) return;
    const page = PAGES.find((p) => p.id === PAGE);
    if (page && page.num && /^L\d/.test(PAGE)) hero.dataset.num = page.num;
    const words = (document.querySelector("main.content").innerText || "").split(/\s+/).length;
    const meta = hero.querySelector(".meta");
    if (meta && /^L\d/.test(PAGE)) meta.insertAdjacentHTML("beforeend", '<span class="chip read">≈ ' + Math.max(1, Math.round(words / 220)) + " min read</span>");
  }

  function slug(s) {
    return s.toLowerCase().replace(/<[^>]+>/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60);
  }

  function buildPageToc(box) {
    // ids must match tools/build_index.py, which links search hits to these anchors
    document.querySelectorAll("main.content h3").forEach((h) => { if (!h.id) h.id = slug(h.textContent); });
    const hs = [...document.querySelectorAll("main.content h2")];
    hs.forEach((h) => { if (!h.id) h.id = slug(h.textContent); });
    document.querySelectorAll("a[data-req]").forEach((a) => {
      if (AVAILABLE && !AVAILABLE.includes(a.dataset.req)) { a.classList.add("soon"); a.removeAttribute("href"); }
    });
    if (!box) return;
    if (!hs.length) { box.remove(); return; }
    box.innerHTML = hs.map((h) => '<a href="#' + h.id + '">' + (h.dataset.short || h.textContent.replace(/§.*$/, "").trim()) + "</a>").join("");
    const links = [...box.querySelectorAll("a")];
    const onScroll = () => {
      let cur = 0;
      hs.forEach((h, i) => { if (h.getBoundingClientRect().top < 120) cur = i; });
      links.forEach((a, i) => a.classList.toggle("current", i === cur));
    };
    document.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
  }

  function buildPager(main) {
    const list = PAGES.filter((p) => !AVAILABLE || AVAILABLE.includes(p.id));
    const i = list.findIndex((p) => p.id === PAGE);
    if (i < 0 || PAGE === "home") return;
    const prev = list[i - 1], next = list[i + 1];
    const pg = el("nav", { class: "pager" });
    pg.innerHTML =
      (prev ? '<a href="' + url(prev.href) + '"><div class="dir">&larr; Previous</div>' + (prev.num ? prev.num + ". " : "") + prev.title + "</a>" : "<span></span>") +
      (next ? '<a class="next" href="' + url(next.href) + '"><div class="dir">Next &rarr;</div>' + (next.num ? next.num + ". " : "") + next.title + "</a>" : "<span></span>");
    main.appendChild(pg);
  }

  function buildDoneToggle() {
    const hero = document.querySelector(".hero");
    if (!hero || !/^L\d/.test(PAGE)) return;
    const btn = el("button", { class: "icon-btn done-toggle", type: "button" });
    const paint = () => {
      const d = store.get("done", {})[PAGE];
      btn.classList.toggle("is-done", !!d);
      btn.textContent = d ? "✓ Studied — click to unmark" : "Mark lecture as studied";
    };
    btn.addEventListener("click", () => {
      const d = store.get("done", {});
      d[PAGE] = !d[PAGE];
      store.set("done", d);
      paint();
      const dot = document.querySelector('.sidebar a[data-id="' + PAGE + '"]');
      if (dot) {
        const old = dot.querySelector(".done-dot");
        if (d[PAGE] && !old) dot.insertAdjacentHTML("beforeend", '<span class="done-dot"></span>');
        if (!d[PAGE] && old) old.remove();
      }
    });
    paint();
    hero.appendChild(btn);
  }

  /* ---------- Search (index in assets/search-index.js, built by tools/build_index.py) ---------- */
  function setupSearch(top) {
    const input = top.querySelector(".search-input");
    const out = top.querySelector(".search-results");
    let sel = -1;
    const run = () => {
      const q = input.value.trim().toLowerCase();
      const idx = window.RL_SEARCH || [];
      if (q.length < 2) { out.classList.remove("open"); return; }
      const terms = q.split(/\s+/);
      const hits = idx.filter((r) => terms.every((t) => (r.t + " " + (r.k || "")).toLowerCase().includes(t))).slice(0, 14);
      out.innerHTML = hits.length
        ? hits.map((r) => '<a href="' + url(r.u) + '">' + r.t + '<div class="where">' + r.p + "</div></a>").join("")
        : '<div class="muted small" style="padding:8px 10px">No matches</div>';
      sel = -1;
      out.classList.add("open");
    };
    input.addEventListener("input", run);
    input.addEventListener("focus", run);
    input.addEventListener("keydown", (e) => {
      const as = [...out.querySelectorAll("a")];
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault();
        sel = Math.max(0, Math.min(as.length - 1, sel + (e.key === "ArrowDown" ? 1 : -1)));
        as.forEach((a, i) => a.classList.toggle("sel", i === sel));
      } else if (e.key === "Enter" && as.length) {
        location.href = as[Math.max(sel, 0)].href;
      } else if (e.key === "Escape") { out.classList.remove("open"); input.blur(); }
    });
    document.addEventListener("click", (e) => { if (!e.target.closest(".search-wrap")) out.classList.remove("open"); });
  }

  /* ---------- Quiz helpers ---------- */
  function setupQuiz() {
    document.querySelectorAll(".quiz").forEach((q) => {
      const tools = el("div", { class: "quiz-tools" });
      tools.innerHTML = '<button class="btn ghost" type="button" data-a="open">Reveal all answers</button>' +
        '<button class="btn ghost" type="button" data-a="close">Hide all</button>';
      q.insertBefore(tools, q.firstChild);
      tools.addEventListener("click", (e) => {
        const a = e.target.dataset.a;
        if (!a) return;
        q.querySelectorAll("details").forEach((d) => (d.open = a === "open"));
      });
    });
  }

  /* ---------- Math ---------- */
  function renderMath() {
    if (!window.renderMathInElement) return;
    renderMathInElement(document.querySelector("main.content"), {
      delimiters: [
        { left: "$$", right: "$$", display: true },
        { left: "\\[", right: "\\]", display: true },
        { left: "$", right: "$", display: false },
        { left: "\\(", right: "\\)", display: false },
      ],
      macros: {
        "\\E": "\\mathbb{E}",
        "\\Pr": "\\operatorname{Pr}",
        "\\argmax": "\\operatorname*{arg\\,max}",
        "\\argmin": "\\operatorname*{arg\\,min}",
        "\\doteq": "\\stackrel{.}{=}",
        "\\w": "\\mathbf{w}",
        "\\x": "\\mathbf{x}",
        "\\VE": "\\overline{\\mathrm{VE}}",
      },
      throwOnError: false,
    });
  }

  /* ---------- Backup diagrams ----------
     <div class="bk" data-tree="s|a3|s2" data-label="..."></div>
     levels separated by "|": first is the root type (s = state, a = action);
     each later level is <type><branching>[m] (m = draw a max arc over that fan),
     "~" draws a gap (…) and "T" a terminal square. */
  function renderBackups() {
    document.querySelectorAll(".bk[data-tree]").forEach((box) => {
      const spec = box.dataset.tree.split("|");
      const levels = [{ t: spec[0], n: 1, max: false }];
      spec.slice(1).forEach((tok) => {
        if (tok === "~") levels.push({ t: "gap", n: 1 });
        else if (tok === "T") levels.push({ t: "T", n: 1 });
        else levels.push({ t: tok[0], n: parseInt(tok.slice(1) || "1", 10), max: /m$/.test(tok) });
      });
      const leaves = levels.reduce((p, l) => p * l.n, 1);
      const dx = 26, dy = 34, pad = 14;
      const W = Math.max(40, (leaves - 1) * dx + pad * 2), H = (levels.length - 1) * dy + pad * 2;
      let nodes = [{ x: W / 2, y: pad, t: levels[0].t }];
      let parts = [];
      let shapes = [];
      let span = (leaves - 1) * dx;
      let parents = [{ x: W / 2, lo: W / 2 - span / 2, hi: W / 2 + span / 2 }];
      const drawNode = (n) => {
        if (n.t === "s") shapes.push('<circle cx="' + n.x + '" cy="' + n.y + '" r="7" fill="var(--node-fill)" stroke="var(--text)" stroke-width="1.5"/>');
        else if (n.t === "a") shapes.push('<circle cx="' + n.x + '" cy="' + n.y + '" r="4.5" fill="var(--text)"/>');
        else if (n.t === "T") shapes.push('<rect x="' + (n.x - 7) + '" y="' + (n.y - 7) + '" width="14" height="14" fill="var(--surface-2)" stroke="var(--text)" stroke-width="1.5"/>');
        else if (n.t === "gap") shapes.push('<text x="' + n.x + '" y="' + (n.y + 4) + '" text-anchor="middle" font-size="16">⋮</text>');
      };
      drawNode(nodes[0]);
      for (let L = 1; L < levels.length; L++) {
        const lv = levels[L], y = pad + L * dy;
        const next = [];
        parents.forEach((p) => {
          const kids = [];
          const w = (p.hi - p.lo) / lv.n;
          for (let k = 0; k < lv.n; k++) {
            const lo = p.lo + k * w, hi = lo + w;
            const x = lv.n === 1 ? p.x : (lo + hi) / 2;
            kids.push({ x, lo, hi });
            const y0 = y - dy;
            if (lv.t !== "gap" && levels[L - 1].t !== "gap") parts.push('<line x1="' + p.x + '" y1="' + (y0 + 7) + '" x2="' + x + '" y2="' + (y - 7) + '" stroke="var(--text)" stroke-width="1.2"/>');
            drawNode({ x, y, t: lv.t });
          }
          if (lv.max && kids.length > 1) {
            const a = kids[0], b = kids[kids.length - 1], ym = y - dy * 0.45;
            const fx = (xx) => p.x + (xx - p.x) * 0.55;
            parts.push('<path d="M' + fx(a.x) + "," + ym + " Q" + p.x + "," + (ym + 9) + " " + fx(b.x) + "," + ym + '" fill="none" stroke="var(--pit)" stroke-width="1.5"/>');
          }
          kids.forEach((k) => next.push(k));
        });
        // centre each kid over its own subtree span for the following levels
        parents = next.map((k) => ({ x: k.x, lo: k.lo + (k.hi - k.lo) / 2 - (k.hi - k.lo) / 2, hi: k.hi }));
      }
      const svg = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + " " + H + '" role="img" aria-label="Backup diagram">' + parts.join("") + shapes.join("") + "</svg>";
      box.innerHTML = svg + (box.dataset.label ? '<div class="bk-label">' + box.dataset.label + "</div>" : "");
    });
  }

  /* ---------- Line chart ----------
     RL.lineChart(container, {
       x: [..] (shared x values), series: [{name, color: "var(--s1)", y: [..]}],
       xLabel, yLabel, yMin, yMax, xFmt, yFmt, height, logX })
     2px lines, hairline grid, legend above, crosshair + tooltip on hover. */
  function lineChart(container, o) {
    const W = 720, H = o.height || 300, m = { l: 52, r: 16, t: 10, b: 40 };
    const xs = o.x, n = xs.length;
    const all = [];
    o.series.forEach((s) => s.y.forEach((v) => { if (v != null && isFinite(v)) all.push(v); }));
    let y0 = o.yMin != null ? o.yMin : Math.min(...all), y1 = o.yMax != null ? o.yMax : Math.max(...all);
    if (y0 === y1) { y0 -= 1; y1 += 1; }
    const tx = (v) => (o.logX ? Math.log(v) : v);
    const xa = tx(xs[0]), xb = tx(xs[n - 1]);
    const X = (v) => m.l + ((tx(v) - xa) / (xb - xa || 1)) * (W - m.l - m.r);
    const Y = (v) => m.t + (1 - (v - y0) / (y1 - y0)) * (H - m.t - m.b);
    const yf = o.yFmt || ((v) => +v.toFixed(3));
    const xf = o.xFmt || ((v) => v);
    const ticks = niceTicks(y0, y1, 5);
    const xticks = o.xTicks || niceTicks(xs[0], xs[n - 1], 6).filter((v) => v >= xs[0] && v <= xs[n - 1]);
    let g = '<g class="grid">' + ticks.map((t) => '<line x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + Y(t) + '" y2="' + Y(t) + '"/>').join("") + "</g>";
    g += '<g class="axis">' + ticks.map((t) => '<text x="' + (m.l - 8) + '" y="' + (Y(t) + 4) + '" text-anchor="end">' + yf(t) + "</text>").join("") +
      xticks.map((t) => '<text x="' + X(t) + '" y="' + (H - m.b + 16) + '" text-anchor="middle">' + xf(t) + "</text>").join("") +
      '<line x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + (H - m.b) + '" y2="' + (H - m.b) + '"/></g>';
    if (o.xLabel) g += '<text class="ax-title" x="' + ((m.l + W - m.r) / 2) + '" y="' + (H - 4) + '" text-anchor="middle">' + o.xLabel + "</text>";
    if (o.yLabel) g += '<text class="ax-title" transform="translate(13,' + ((m.t + H - m.b) / 2) + ') rotate(-90)" text-anchor="middle">' + o.yLabel + "</text>";
    const paths = o.series.map((s) => {
      let d = "", pen = false;
      s.y.forEach((v, i) => {
        if (v == null || !isFinite(v) || v < y0 - (y1 - y0) || v > y1 + (y1 - y0)) { pen = false; return; }
        const vv = Math.max(y0, Math.min(y1, v));
        d += (pen ? "L" : "M") + X(xs[i]).toFixed(1) + "," + Y(vv).toFixed(1);
        pen = true;
      });
      const dots = o.markers ? s.y.map((v, i) => (v == null ? "" : '<circle cx="' + X(xs[i]) + '" cy="' + Y(Math.max(y0, Math.min(y1, v))) + '" r="4" fill="' + s.color + '" stroke="var(--surface)" stroke-width="2"/>')).join("") : "";
      return '<path d="' + d + '" stroke="' + s.color + '"' + (s.dash ? ' stroke-dasharray="5 4"' : "") + "/>" + dots;
    }).join("");
    const legend = o.series.length > 1
      ? '<div class="legend">' + o.series.map((s) => '<span class="li"><span class="sw" style="background:' + s.color + '"></span>' + s.name + "</span>").join("") + "</div>"
      : "";
    container.classList.add("chart");
    container.innerHTML = legend + '<svg viewBox="0 0 ' + W + " " + H + '" preserveAspectRatio="xMidYMid meet">' + g +
      '<g class="series">' + paths + '</g><line class="xhair" y1="' + m.t + '" y2="' + (H - m.b) + '" visibility="hidden"/>' +
      '<rect class="hit" x="' + m.l + '" y="' + m.t + '" width="' + (W - m.l - m.r) + '" height="' + (H - m.t - m.b) + '" fill="transparent"/></svg>' +
      '<div class="tip" hidden></div>';
    const svg = container.querySelector("svg"), tip = container.querySelector(".tip"), xh = container.querySelector(".xhair");
    const hit = container.querySelector(".hit");
    const move = (ev) => {
      const r = svg.getBoundingClientRect();
      const px = ((ev.clientX - r.left) / r.width) * W;
      let best = 0, bd = Infinity;
      xs.forEach((v, i) => { const d = Math.abs(X(v) - px); if (d < bd) { bd = d; best = i; } });
      const cx = X(xs[best]);
      xh.setAttribute("x1", cx); xh.setAttribute("x2", cx); xh.setAttribute("visibility", "visible");
      tip.hidden = false;
      tip.innerHTML = '<div class="muted" style="margin-bottom:4px">' + (o.xLabel || "x") + " = " + xf(xs[best]) + "</div>" +
        o.series.map((s) => '<div class="row"><span><span class="sw" style="background:' + s.color + '"></span>' + s.name + '</span><span class="v">' +
          (s.y[best] == null ? "–" : yf(s.y[best])) + "</span></div>").join("");
      const left = (cx / W) * r.width;
      const tw = tip.offsetWidth;
      tip.style.left = Math.min(Math.max(0, left + 12), r.width - tw) + "px";
      tip.style.top = (container.querySelector(".legend") ? 28 : 4) + "px";
    };
    hit.addEventListener("mousemove", move);
    hit.addEventListener("touchstart", (e) => move(e.touches[0]), { passive: true });
    hit.addEventListener("mouseleave", () => { tip.hidden = true; xh.setAttribute("visibility", "hidden"); });
  }

  function niceTicks(a, b, count) {
    const span = b - a || 1;
    const step0 = span / count;
    const mag = Math.pow(10, Math.floor(Math.log10(step0)));
    const err = step0 / mag;
    const step = (err >= 7.5 ? 10 : err >= 3.5 ? 5 : err >= 1.5 ? 2 : 1) * mag;
    const out = [];
    for (let v = Math.ceil(a / step) * step; v <= b + step * 1e-9; v += step) out.push(+v.toFixed(10));
    return out;
  }

  // Seedable RNG so demos are reproducible when asked to be.
  function rng(seed) {
    let s = seed >>> 0 || 1;
    const f = () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
    f.normal = () => { let u = 0, v = 0; while (u === 0) u = f(); v = f(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
    f.int = (n) => Math.floor(f() * n);
    return f;
  }

  window.RL = { lineChart, rng, store, niceTicks };

  function init() {
    buildChrome();
    renderBackups();
    setupQuiz();
    renderMath();
    document.dispatchEvent(new CustomEvent("rl:ready"));
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
